using System; using System.Windows; namespace KKBOT.ControlCenter.Wpf; public partial class App : Application { protected override void OnStartup(StartupEventArgs e) { base.OnStartup(e); // Register services for MVVM (simplified) var services = new Microsoft.Extensions.DependencyInjection.ServiceCollection(); services.AddLogging(); services.AddSingleton<Microsoft.Extensions.Logging.ILoggerFactory, Microsoft.Extensions.Logging.LoggerFactory>(); services.AddSingleton<Microsoft.Extensions.Logging.ILogger>(sp => sp.GetRequiredService<Microsoft.Extensions.Logging.ILoggerFactory>().CreateLogger("Wpf")); services.AddMediatR(typeof(App).Assembly); var provider = services.BuildServiceProvider(); Resources["Mediator"] = provider.GetRequiredService<MediatR.IMediator>(); } }